SELECT gadget_title, replacement_cost
FROM gadget
WHERE replacement_cost > 500;

SELECT gadget_title, daily_fee
FROM gadget
ORDER BY daily_fee DESC, gadget_title;

SELECT DISTINCT power_source
FROM gadget
ORDER BY power_source;

SELECT gadget_title
FROM gadget
WHERE gadget_title LIKE '%SAW%';

SELECT maker_name, home_region
FROM maker
WHERE home_region IN ('Canada', 'Japan');

SELECT checkout_id, unit_id, checked_out_on
FROM checkout
WHERE checked_out_on BETWEEN '2024-06-01' AND '2024-08-31';

SELECT checkout_id, unit_id, due_on
FROM checkout
WHERE returned_on IS NULL;

SELECT sum(amount)
FROM ledger_entry
WHERE entry_kind = 'Late fee';

SELECT count(*)
FROM checkout
WHERE patron_id = 34;

SELECT count(*)
FROM checkout
WHERE month(checked_out_on) = 7;

UPDATE gadget
SET daily_fee = daily_fee + 2.00
WHERE power_source = 'Gas';
